import{G as e,K as t,at as n,j as r}from"./chunks/framework.DrNIf5Lg.js";var i=JSON.parse(`{"title":"贡献指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contributing/index.md","filePath":"zh/contributing/index.md"}`),a={name:`zh/contributing/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="贡献指南" tabindex="-1">贡献指南 <a class="header-anchor" href="#贡献指南" aria-label="Permalink to “贡献指南”">​</a></h1><p>StaticPHP 欢迎修复、Package 定义、平台支持、测试和文档贡献。v3 的部分扩展 API 仍在定型，因此需要区分对内置 <code>core</code> Registry 的贡献，以及依赖长期兼容契约的外部 Registry。</p><h2 id="开发环境" tabindex="-1">开发环境 <a class="header-anchor" href="#开发环境" aria-label="Permalink to “开发环境”">​</a></h2><p>检出源码需要 PHP 8.4 或更高版本及 Composer。CLI 还需要<a href="/zh/guide/installation.html">源码安装指南</a>中列出的 PHP 扩展。在仓库根目录安装开发依赖：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/spc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>只有修改 VitePress 文档时才需要 Node.js 和 npm：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>尝试真实构建前，请运行 <code>bin/spc doctor</code>。完整静态构建依赖平台且可能耗时较长，因此不是每个纯文档、测试或配置改动的前置条件。</p><h2 id="选择正确的层级" tabindex="-1">选择正确的层级 <a class="header-anchor" href="#选择正确的层级" aria-label="Permalink to “选择正确的层级”">​</a></h2><p>应把改动放在能够表达需求的最小层级：</p><table tabindex="0"><thead><tr><th>区域</th><th>用途</th></tr></thead><tbody><tr><td><code>config/pkg/ext/</code></td><td>PHP 扩展 Package 定义</td></tr><tr><td><code>config/pkg/lib/</code></td><td>链接期依赖库定义</td></tr><tr><td><code>config/pkg/target/</code></td><td>最终和虚拟构建 target</td></tr><tr><td><code>config/pkg/tool/</code></td><td>宿主机侧构建工具 Package</td></tr><tr><td><code>config/artifact/</code></td><td>共享或复杂的源码/二进制 Artifact 定义</td></tr><tr><td><code>src/Package/</code></td><td>Package 专属 recipe、patch、hook 和自定义 Artifact 行为</td></tr><tr><td><code>src/StaticPHP/</code></td><td>框架、resolver、runtime、Doctor、Registry 和命令实现</td></tr><tr><td><code>tests/</code></td><td>PHPUnit 测试和 fixture</td></tr><tr><td><code>docs/en/</code>、<code>docs/zh/</code></td><td>英文规范文档及其同步的中文版本</td></tr></tbody></table><p>优先使用声明式 YAML 字段，不要用 PHP 条件代替。只有 Package 需要构建命令、源码改写、校验、自定义 configure 参数或 lifecycle hook 时，才增加 recipe class。</p><p>不要通过编辑生成的 <code>buildroot/</code>、<code>source/</code>、<code>downloads/</code> 或 <code>pkgroot/</code> 内容修复问题。这些改动会被丢弃，也无法说明其他用户如何复现构建。</p><h2 id="添加或更新-package" tabindex="-1">添加或更新 Package <a class="header-anchor" href="#添加或更新-package" aria-label="Permalink to “添加或更新 Package”">​</a></h2><p>编写新定义前，先搜索使用相同构建系统和 Artifact 类型的 Package，沿用其结构，然后检查：</p><ol><li>选择正确类型：<code>php-extension</code>、<code>library</code>、<code>target</code>、<code>virtual-target</code> 或 <code>tool</code>。</li><li>使用精确的 Package 名。PHP 扩展依赖和配置使用 <code>ext-</code> 前缀。</li><li>硬依赖放在 <code>depends</code>，可选关系放在 <code>suggests</code>，宿主机构建工具放在 <code>tools</code>。</li><li>Schema 支持时，通过 <code>@windows</code>、<code>@unix</code>、<code>@linux</code> 或 <code>@macos</code> 字段表达平台差异。</li><li>单个 Package 的简单源码优先使用内联 Artifact；多个 Package 共用，或自定义行为更适合独立定义时，使用 <code>config/artifact/</code>。</li><li>在 Artifact metadata 中记录许可证标识和文件。只有需要在源码构建后复制许可证内容时，才增加结构化 Package <code>license</code> 条目。</li><li>只有配置不足以表达行为时，才增加或修改相应 PHP recipe。</li></ol><p>当前 schema 参见 <a href="/zh/develop/package-model.html">Package 模型</a>和 <a href="/zh/develop/artifact-model.html">Artifact 模型</a>。</p><p>配置校验会严格拒绝未知字段，但无法证明 URL 存在、patch 仍可应用，或库能在所有平台链接。条件允许时，应测试受影响的最旧和最新 PHP 分支，以及本次改动涉及的平台。</p><h2 id="php-代码和测试" tabindex="-1">PHP 代码和测试 <a class="header-anchor" href="#php-代码和测试" aria-label="Permalink to “PHP 代码和测试”">​</a></h2><p>StaticPHP 遵循仓库现有代码风格，并优先沿用现有 Package/构建模式，而不是增加新抽象。修改框架代码时：</p><ul><li>内部编排细节应保持为内部实现；PHP 的 <code>public</code> 可见性本身不代表受支持的扩展 API。</li><li>为 resolver、config、Registry、命令或工具行为增加针对性的 PHPUnit 测试。</li><li>把失败输入或回归场景写入测试，不要只依赖一次手动构建。</li><li>不要在同一 PR 中混入无关格式化或机械改动。</li></ul><p>测试位于 <code>tests/StaticPHP/</code>，使用 <code>Tests\\StaticPHP\\</code> namespace。开发时先运行最小相关测试，提交前再执行项目检查。</p><h2 id="doctor-改动" tabindex="-1">Doctor 改动 <a class="header-anchor" href="#doctor-改动" aria-label="Permalink to “Doctor 改动”">​</a></h2><p>内置 Doctor check 当前位于 <code>src/StaticPHP/Doctor/Item/</code>。Check 应只观察环境，不修改它；安装、下载和文件写入应放在单独的 fix callback 中。</p><p>当前 Attribute 和 callback 签名属于内部实现，并有原始 fix 参数、修复后不自动重查等已知限制。维护内置检查时可以沿用现有 core check，但不能把该模式描述为稳定的第三方 API。用户可见的 check、fix、前置条件或 lock 行为变化时，应更新 <a href="/zh/develop/doctor-module.html">Doctor 环境检查</a>和<a href="/zh/develop/system-build-tools.html">编译工具</a>。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to “文档”">​</a></h2><p><code>docs/en/</code> 下的英文是规范版本。每个英文 Markdown 文件都必须在 <code>docs/zh/</code> 下有对应文件；两个版本必须拥有相同的标题、示例、表格、admonition，并链接到相应语言路径。</p><p>行为变化时，应更新所有描述该行为的页面，而不只是最接近的参考页。常见情况包括 CLI 选项、环境变量、Package/Artifact 字段、Doctor 检查和迁移说明。</p><p>验证文件树一致并构建站点：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/en </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*.md&#39; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s|docs/en/||&#39; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/zh </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*.md&#39; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s|docs/zh/||&#39; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>新增页面时，还必须同步加入两个 VitePress sidebar。</p><h2 id="验证清单" tabindex="-1">验证清单 <a class="header-anchor" href="#验证清单" aria-label="Permalink to “验证清单”">​</a></h2><p>根据改动范围运行相应检查：</p><table tabindex="0"><thead><tr><th>改动</th><th>必需检查</th></tr></thead><tbody><tr><td>Package、Artifact、target、extension、library 或 tool 配置</td><td><code>bin/spc dev:lint-config</code>、<code>composer cs-fix</code></td></tr><tr><td>PHP 框架或 recipe 代码</td><td><code>composer cs-fix</code>、<code>composer test</code>、<code>composer analyse</code></td></tr><tr><td>文档</td><td>中英文文件树和结构检查、<code>npm run docs:build</code></td></tr><tr><td>平台构建修复</td><td>上述检查，加上条件允许时最小的受影响构建或 CI matrix</td></tr></tbody></table><p>常用命令：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin/spc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:lint-config</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cs-fix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyse</span></span></code></pre></div><p>本地无法运行完整构建时，应说明哪些平台/PHP 组合尚未测试，并附相关日志或 CI 结果。构建和 shell 日志默认位于 <code>log/</code>，但通常不应提交生成的日志。</p><h2 id="pull-request" tabindex="-1">Pull Request <a class="header-anchor" href="#pull-request" aria-label="Permalink to “Pull Request”">​</a></h2><p>每个 Pull Request 应保持聚焦，并说明：</p><ul><li>问题是什么，以及为什么选择当前修改层级。</li><li>受影响的 Package/Artifact、目标 OS、架构、toolchain 和 PHP 版本。</li><li>用户可见行为或兼容性影响。</li><li>已运行的测试和构建，包括尚未测试的部分。</li><li>已同步更新的两种语言文档。</li></ul><p>完成仓库的 Pull Request checklist。不要提交生成的构建目录、下载归档、缓存、本地环境文件或无关的编辑器/操作系统元数据。</p><p>新增依赖或随附 patch 时，应包含上游来源、许可证和需要该内容的条件。优先推动上游修复，并将下游 patch 限制在受影响版本。</p><h2 id="安全问题报告" tabindex="-1">安全问题报告 <a class="header-anchor" href="#安全问题报告" aria-label="Permalink to “安全问题报告”">​</a></h2><p>不要在普通 issue 中公开漏洞利用细节、凭据、签名材料或可复现的漏洞。仓库支持时请使用 GitHub private vulnerability reporting，或通过现有项目渠道联系维护者，安排私下披露。</p><p>仓库目前没有专用 <code>SECURITY.md</code>；补充正式的支持版本和披露策略仍是项目维护事项。</p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};